"""Independent parsers verify bytes generated by the native ASM exporters."""
import csv
from datetime import datetime, timezone
import io
import json
import random
import unittest
from server import Server


class NativeExportTests(unittest.TestCase):
    def setUp(self):
        self.server = Server()
        self.addCleanup(self.server.close)
        self.cookie = self.server.session()

    def get(self, path, cookie=None, method='GET'):
        return self.server.request(method, path, cookie=cookie or self.cookie)

    def fixture(self, records):
        self.server.file(self.cookie).write_text(''.join(
            f'{i}|{done}|{timestamp}|{title}\n'
            for i, done, timestamp, title in records), encoding='utf8')

    def test_export_requires_own_session_and_has_download_policy(self):
        for path, mime in [('/export.json', 'application/json'), ('/export.csv', 'text/csv'), ('/export.ics', 'text/calendar')]:
            with self.subTest(path=path):
                self.assertEqual(self.server.request('GET', path)[0], 401)
                status, headers, body = self.get(path)
                self.assertEqual(status, 200)
                self.assertTrue(headers['Content-Type'].startswith(mime))
                self.assertIn('attachment', headers['Content-Disposition'])
                self.assertIn('noindex', headers['X-Robots-Tag'])
                self.assertIn('no-store', headers['Cache-Control'])
                self.assertEqual(int(headers['Content-Length']), len(body))
                hs, hh, hb = self.get(path, method='HEAD')
                self.assertEqual(hs, 200)
                self.assertEqual(hb, b'')
                # JSON export time may tick between GET and HEAD; length is fixed.
                self.assertEqual(hh['Content-Length'], headers['Content-Length'])
                self.assertEqual(self.server.request('POST', path, '', cookie=self.cookie)[0], 404)

    def test_json_escaping_unicode_isolation_and_64_bit_ids(self):
        title = 'Ședință 😀 <script> "quoted" \\ backslash'
        self.fixture([(9223372036854775806, 1, 1700000000, title)])
        body = self.get('/export.json')[2]
        document = json.loads(body)
        self.assertEqual(document['version'], 2)
        self.assertEqual([{key: task[key] for key in ['id','title','completed','createdAt']} for task in document['tasks']], [{
            'id': '9223372036854775806', 'title': title, 'completed': True,
            'createdAt': '2023-11-14T22:13:20Z'}])
        self.assertNotIn(self.cookie.split('=')[1].encode(), body)
        other = self.server.session()
        self.assertEqual(json.loads(self.get('/export.json', other)[2])['tasks'], [])

    def test_csv_roundtrip_quotes_commas_unicode_and_formula_defense(self):
        titles = ['a,b "quoted" 😀', '=1+1', '+cmd', '-1', '@SUM(A1)',
                  '  =1', '\u00a0=1', '\u1680+1', '\u2003-1', '\u202f@A1', '\u205f=1', '\u3000=1', '\ufeff=1']
        self.fixture([(i, 0, 0, title) for i, title in enumerate(titles, 1)])
        body = self.get('/export.csv')[2]
        rows = list(csv.DictReader(io.StringIO(body.decode('utf-8-sig'))))
        self.assertEqual(len(rows), len(titles))
        for i, (title, row) in enumerate(zip(titles, rows)):
            self.assertEqual(row['title'], title if i == 0 else "'"+title)
            self.assertEqual(row['createdAt'], '1970-01-01T00:00:00Z')
            self.assertEqual(row['completed'], 'false')

    def test_native_calendar_matches_independent_calendar(self):
        randomizer = random.Random(2984)
        timestamps = [0, 951782400, 4107542400, 253402300799, 2147483647,
                      *[randomizer.randrange(253402300800) for _ in range(250)]]
        self.fixture([(i, 0, stamp, 'date') for i, stamp in enumerate(timestamps, 1)])
        records = json.loads(self.get('/export.json')[2])['tasks']
        for stamp, record in zip(timestamps, records):
            self.assertEqual(record['createdAt'], datetime.fromtimestamp(stamp, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'))

    def test_invalid_calendar_date_is_null_not_invalid_json(self):
        self.fixture([(1, 0, 9223372036854775807, 'legacy timestamp')])
        self.assertIsNone(json.loads(self.get('/export.json')[2])['tasks'][0]['createdAt'])
        row = list(csv.DictReader(io.StringIO(self.get('/export.csv')[2].decode('utf-8-sig'))))[0]
        self.assertEqual(row['createdAt'], '')

    def test_maximum_export_and_legacy_tombstones(self):
        self.fixture([(i, i % 2, 1700000000, '"'*110) for i in range(1, 1001)])
        path = self.server.file(self.cookie)
        with path.open('a') as handle:
            handle.write('1000|2|1700000000|deleted\n')
        for route in ['/export.json', '/export.csv']:
            status, headers, body = self.get(route)
            self.assertEqual(status, 200)
            self.assertEqual(int(headers['Content-Length']), len(body))
            self.assertLess(len(body), 2097152)
            records = json.loads(body)['tasks'] if route.endswith('json') else list(csv.DictReader(io.StringIO(body.decode('utf-8-sig'))))
            self.assertEqual(len(records), 999)

    def test_invalid_stored_utf8_fails_closed(self):
        path = self.server.file(self.cookie)
        path.write_bytes(b'1|0|1|invalid\xff\n')
        for route in ['/export.json', '/export.csv', '/app']:
            self.assertEqual(self.get(route)[0], 500)
        self.assertEqual(path.read_bytes(), b'1|0|1|invalid\xff\n')
